import {
  EndpointSelectQuery,
  EndpointSelectQuery$data,
} from '../../__generated__/EndpointSelectQuery.graphql';
import { EndpointSelectValueQuery } from '../../__generated__/EndpointSelectValueQuery.graphql';
import { useWebUINavigate } from '../../hooks';
import { useLazyPaginatedQuery } from '../../hooks/usePaginatedQuery';
import { useProjectPath } from '../../hooks/useRouteScope';
import TotalFooter from '../TotalFooter';
import { useControllableValue } from 'ahooks';
import {
  Button,
  type GetRef,
  type SelectProps,
  Skeleton,
  Space,
  Tooltip,
} from 'antd';
import {
  BAIEndpointsIcon,
  BAIFlex,
  BAISelect,
  mergeFilterValues,
} from 'backend.ai-ui';
import * as _ from 'lodash-es';
import { InfoIcon } from 'lucide-react';
import React, { useDeferredValue, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { graphql, useLazyLoadQuery } from 'react-relay';

export type Endpoint = NonNullable<
  NonNullableItem<EndpointSelectQuery$data['endpoint_list']>
>;

export interface EndpointSelectProps extends Omit<
  SelectProps,
  'options' | 'labelInValue'
> {
  fetchKey?: string;
  showDetailPageButton?: boolean;
}

type LifecycleStage =
  | 'pending'
  | 'created' // Deprecated, use READY instead from 25.13.0
  | 'scaling'
  | 'ready'
  | 'destroying'
  | 'destroyed';

// Terminated lifecycle stages: a deployment in one of these has no serving
// replica. Everything else may still have a replica serving traffic.
const TERMINATED_LIFECYCLE_STAGES: LifecycleStage[] = [
  'destroying',
  'destroyed',
];

const EndpointSelect: React.FC<EndpointSelectProps> = ({
  fetchKey,
  showDetailPageButton: showInfoButton,
  loading,
  ...selectPropsWithoutLoading
}) => {
  const { t } = useTranslation();

  const [controllableValue, setControllableValue] = useControllableValue<
    string | undefined
  >(selectPropsWithoutLoading);
  const [controllableOpen, setControllableOpen] = useControllableValue<boolean>(
    selectPropsWithoutLoading,
    {
      valuePropName: 'open',
      trigger: 'onOpenChange',
      defaultValuePropName: 'defaultOpen',
    },
  );
  const deferredOpen = useDeferredValue(controllableOpen);
  const [searchStr, setSearchStr] = useState<string>();
  const deferredSearchStr = useDeferredValue(searchStr);

  const selectRef = useRef<GetRef<typeof BAISelect> | null>(null);

  // Show every deployment that is not terminated, so a deployment whose replica
  // is still alive stays selectable while a new revision is rolling out (e.g.
  // deploying/pending). Filtering on ready/created alone hid such deployments.
  // TODO(FR-3303): once the endpoint connection supports nested filters, list
  // deployments that have at least one replica with an active traffic status
  // instead of relying on the endpoint-level lifecycle_stage.
  const lifecycleStageFilterStr = mergeFilterValues(
    TERMINATED_LIFECYCLE_STAGES.map((stage) => `lifecycle_stage != "${stage}"`),
  );

  const { endpoint: selectedEndpoint } =
    useLazyLoadQuery<EndpointSelectValueQuery>(
      graphql`
        query EndpointSelectValueQuery($endpoint_id: UUID!) {
          endpoint(endpoint_id: $endpoint_id) {
            name
            endpoint_id @required(action: NONE)
            url
          }
        }
      `,
      {
        endpoint_id: controllableValue ?? '',
      },
      {
        // to skip the query when controllableValue is empty
        fetchPolicy: controllableValue ? 'store-or-network' : 'store-only',
      },
    );

  const {
    paginationData,
    result: { endpoint_list },
    loadNext,
    isLoadingNext,
  } = useLazyPaginatedQuery<
    EndpointSelectQuery,
    NonNullable<
      EndpointSelectQuery['response']['endpoint_list']
    >['items'][number]
  >(
    graphql`
      query EndpointSelectQuery(
        $offset: Int!
        $limit: Int!
        $projectID: UUID
        $filter: String
      ) {
        endpoint_list(
          offset: $offset
          limit: $limit
          project: $projectID
          filter: $filter
        ) {
          total_count
          items {
            name
            endpoint_id @required(action: NONE)
            url
          }
        }
      }
    `,
    {
      limit: 10,
    },
    {
      filter: mergeFilterValues([
        lifecycleStageFilterStr,
        deferredSearchStr ? `name ilike "%${deferredSearchStr}%"` : undefined,
      ]),
    },
    // TODO: skip fetch when the option popover is closed
    {
      fetchKey,
      fetchPolicy: deferredOpen ? 'network-only' : 'store-only',
    },
    {
      getTotal: (result) => result.endpoint_list?.total_count,
      getItem: (result) => result.endpoint_list?.items,
      getId: (item) => item?.endpoint_id,
    },
  );

  const selectOptions = _.map(paginationData, (item) => {
    return {
      label: item?.name,
      value: item?.endpoint_id,
      endpoint: item,
    };
  });

  const [optimisticValueWithLabel, setOptimisticValueWithLabel] = useState(
    selectedEndpoint
      ? {
          label: selectedEndpoint?.name || undefined,
          value: selectedEndpoint?.endpoint_id || undefined,
        }
      : controllableValue
        ? {
            label: controllableValue,
            value: controllableValue,
          }
        : controllableValue,
  );

  const webuiNavigate = useWebUINavigate();
  const buildProjectPath = useProjectPath();

  const isValueMatched = searchStr === deferredSearchStr;
  useEffect(() => {
    if (isValueMatched) {
      // Scroll dropdown to top position when search completes (search value matches deferred value)
      // This ensures users see the top results immediately after search processing
      selectRef.current?.scrollTo(0);
    }
  }, [isValueMatched]);
  return (
    <BAIFlex direction="row" gap="xs">
      <Space.Compact>
        <BAISelect
          ref={selectRef}
          placeholder={t('chatui.SelectEndpoint')}
          prefix={<BAIEndpointsIcon />}
          header={t('chatui.Deployment')}
          style={{
            minWidth: 100,
            fontWeight: 'normal',
          }}
          showSearch={{
            searchValue: searchStr,
            onSearch: (v) => {
              setSearchStr(v);
            },
            autoClearSearchValue: true,
            filterOption: false,
          }}
          // TODO: Need to make it work properly when autoClearSearchValue is not specified
          loading={searchStr !== deferredSearchStr || loading}
          options={selectOptions}
          {...selectPropsWithoutLoading}
          // override value and onChange
          labelInValue // use labelInValue to display the selected option label
          value={optimisticValueWithLabel}
          onChange={(v, option) => {
            setOptimisticValueWithLabel(v);
            setControllableValue(v.value, _.castArray(option)?.[0].endpoint);
            selectPropsWithoutLoading.onChange?.(v.value || '', option);
          }}
          endReached={() => {
            loadNext();
          }}
          open={controllableOpen}
          onOpenChange={setControllableOpen}
          notFoundContent={
            _.isUndefined(paginationData) ? (
              // For the first loading options
              <Skeleton.Input active size="small" block />
            ) : undefined
          }
          footer={
            _.isNumber(endpoint_list?.total_count) &&
            endpoint_list.total_count > 0 ? (
              <TotalFooter
                loading={isLoadingNext}
                total={endpoint_list?.total_count}
              />
            ) : undefined
          }
        />
        {showInfoButton ? (
          <Tooltip title={t('deployment.GoToDetailPage')}>
            <Button
              icon={<InfoIcon />}
              disabled={!controllableValue}
              onClick={() => {
                webuiNavigate(
                  buildProjectPath(`deployments/${controllableValue}`),
                );
              }}
            />
          </Tooltip>
        ) : null}
      </Space.Compact>
    </BAIFlex>
  );
};

export default EndpointSelect;
